<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Voxel Bonsai Tree</title>

  <style>
    :root {
      color-scheme: light;
      --ink: #263b32;
      --muted: #617368;
      --glass: rgba(248, 252, 247, 0.72);
      --border: rgba(44, 73, 58, 0.16);
      --accent: #477b61;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background:
        radial-gradient(circle at 72% 18%, rgba(255, 255, 255, 0.95), transparent 34%),
        linear-gradient(145deg, #edf3eb 0%, #dce7dc 55%, #c8d8ca 100%);
      color: var(--ink);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
        "Segoe UI", sans-serif;
    }

    #app {
      position: fixed;
      inset: 0;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      touch-action: none;
      cursor: grab;
      outline: none;
    }

    canvas.dragging {
      cursor: grabbing;
    }

    .title-card {
      position: fixed;
      top: 24px;
      left: 24px;
      z-index: 2;
      max-width: min(360px, calc(100vw - 48px));
      padding: 17px 19px;
      border: 1px solid var(--border);
      border-radius: 18px;
      background: var(--glass);
      box-shadow: 0 14px 40px rgba(41, 65, 52, 0.11);
      backdrop-filter: blur(14px);
      -webkit-backdrop-filter: blur(14px);
      pointer-events: none;
    }

    .eyebrow {
      margin: 0 0 5px;
      color: var(--accent);
      font-size: 0.68rem;
      font-weight: 800;
      letter-spacing: 0.18em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-family: Georgia, "Times New Roman", serif;
      font-size: clamp(1.65rem, 4vw, 2.35rem);
      font-weight: 500;
      line-height: 1.05;
    }

    .subtitle {
      margin: 9px 0 0;
      color: var(--muted);
      font-size: 0.84rem;
      line-height: 1.45;
    }

    .controls {
      position: fixed;
      right: 24px;
      bottom: 24px;
      z-index: 3;
      display: flex;
      align-items: center;
